begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);
grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('50000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'role','authenticated','session_id',pg_temp.i(n),'is_anonymous',false)::text,true)$$;
create function pg_temp.ctx(b integer default 101) returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(b))$$;
create function pg_temp.po(ident integer default 800) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('purchaseOrderId',pg_temp.i(ident),'supplierId',pg_temp.i(701),'reference','TEST-PO-'||ident,'expectedOn','2026-11-01','reason','TEST requested ten sacks','items',jsonb_build_array(jsonb_build_object('lineId',pg_temp.i(ident+100),'productId',pg_temp.i(301),'unitId',pg_temp.i(401),'quantity','10')))$$;
create function pg_temp.decision(ident integer default 810,outcome text default 'approve',state text default 'pending',orderid integer default 800) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('purchaseOrderId',pg_temp.i(orderid),'orderEventId',pg_temp.i(ident),'expectedState',state,'outcome',outcome,'reason','TEST owner verified purchase order')$$;
create function pg_temp.delivery(ident integer,accepted text default '0',held text default '0',rejected text default '10',document text default '10') returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('receiptId',pg_temp.i(ident),'purchaseOrderId',pg_temp.i(800),'supplierId',pg_temp.i(701),'reference','TEST-INV-'||ident,'reason','TEST inspected supplier goods','items',jsonb_build_array(jsonb_build_object('orderLineId',pg_temp.i(900),'productId',pg_temp.i(301),'unitId',pg_temp.i(401),'documentQuantity',document,'accepted',accepted,'held',held,'rejected',rejected,'reason','TEST broken packaging and missing sacks')))$$;
create function pg_temp.work() returns jsonb language sql as $$select public.agri_command('purchasing_workspace',pg_temp.ctx())$$;
create function pg_temp.stock() returns numeric language sql as $$select quantity from public.branch_inventory where organization_id=pg_temp.i(1) and branch_id=pg_temp.i(101) and product_id=pg_temp.i(301) and batch_id is null$$;
create function pg_temp.claim(ident integer,outcome text default 'progress',version integer default 0) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('receiptId',pg_temp.i(821),'claimEventId',pg_temp.i(ident),'expectedVersion',version,'outcome',outcome,'reference','TEST supplier credit CN-021','reason','TEST supplier evidence retained')$$;
set local role authenticated;
select pg_temp.login(13);
select pg_temp.login(11);
select pg_temp.login(13);
select pg_temp.login(11);
select public.agri_command('disposition_hold',pg_temp.ctx()||jsonb_build_object('holdId',(select id from public.stock_holds where source_id=pg_temp.i(821)),'dispositionId',pg_temp.i(831),'quantity','25','disposition','release','reason','TEST half sack inspected saleable'));
select public.agri_command('disposition_hold',pg_temp.ctx()||jsonb_build_object('holdId',(select id from public.stock_holds where source_id=pg_temp.i(821)),'dispositionId',pg_temp.i(832),'quantity','25','disposition','supplier_return','reason','TEST supplier acknowledged returned half sack'));
select pg_temp.login(13);
select pg_temp.login(12);
select pg_temp.login(14);
select pg_temp.login(15);
select pg_temp.login(11);
reset role;
set local role authenticated;
select pg_temp.login(11);
do $$declare n integer;begin for n in 1..31 loop perform public.agri_command('create_purchase_order',pg_temp.po(1000+n));end loop;end$$;
reset role;
create function pg_temp.unplanned(ident integer,product integer,unit integer,accepted text,held text,expiry date default null) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('receiptId',pg_temp.i(ident),'purchaseOrderId',null,'supplierId',pg_temp.i(701),'reference','TEST-UNPLANNED-'||ident,'reason','TEST physical inspection','items',jsonb_build_array(jsonb_build_object('productId',pg_temp.i(product),'unitId',pg_temp.i(unit),'documentQuantity','1','accepted',accepted,'held',held,'rejected','0','lot','TEST-REPORTED-LOT','expiresOn',expiry,'reason','TEST lot inspected')))$$;
set local role authenticated;
select pg_temp.login(11);
select pg_temp.login(13);
reset role;
delete from auth.sessions where user_id=pg_temp.i(11);
set local role authenticated;
select pg_temp.login(11);
reset role;
select line from tap_results;
rollback;
